import { Button, Container } from '../../../components'
import { CIRCLE_THUMB_WHITE } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import { WelComeAgentStyle } from './index.style'
// import { LANG_STRINGS } from '../../../lang/index';
import { useCallback, useEffect } from 'react'
import { useAgentLogout, useUpdateGlobal } from '../../../state/globalState/hooks/useGlobalContext'
import { useHistory } from 'react-router-dom'

function WelcomeAgent () {
  // return the Agent welcome screen
  const [, agentLogoutRequest] = useAgentLogout()
  const history = useHistory()
  const [{ globalState: { isLoggedIn } = { }, fcmToken }] = useUpdateGlobal()

  const handleLogout = useCallback(() => {
    agentLogoutRequest({
      fcmToken
    })
  }, [agentLogoutRequest, fcmToken])

  useEffect(() => {
    if (!isLoggedIn) {
      history.replace('/login')
    }
  }, [isLoggedIn, history])

  return (
    <Container
      typeHeader='greeting'
      hideBottomTabs
      hideNotification
      hideHelp
    >
      <WelComeAgentStyle>
        <div className='welcome-thumb'>
          <img src={CIRCLE_THUMB_WHITE} alt='' />
        </div>
        <div className='layer-heading'>{LANG_STRINGS.registrationSuccessful}</div>
        <div className='layer-subHeading'>{LANG_STRINGS.registrationCongrats}</div>
        <Button
          width='50%'
          onClick={handleLogout}
        >
          {LANG_STRINGS.logout}
        </Button>
      </WelComeAgentStyle>
    </Container>
  )
}

export default WelcomeAgent
